function trackClientActivity(client){let pending=0;const active=new Map;for(const[name,action]of Object.entries(client)){if(name==="close"||typeof action!=="function")continue;client[name]=async function(...args){pending++;active.set(name,(active.get(name)||0)+1);try{return await action.apply(this,args)}finally{pending--;const count=active.get(name)-1;count?active.set(name,count):active.delete(name)}}}Object.defineProperty(client,"busy",{get:()=>pending>0});Object.defineProperty(client,"busyExcept",{value:name=>pending>(active.get(name)||0)});return client}export{trackClientActivity as t};
